import { SidebarItem } from './SidebarItem'
import { FOLDERS, type FolderId } from './folders'

type Props = {
  selected: FolderId
  onSelect: (id: FolderId) => void
}

export function Sidebar({ selected, onSelect }: Props) {
  return (
    <nav className="sidebar" aria-label="Folders">
      {FOLDERS.map((folder) => (
        <SidebarItem
          key={folder.id}
          folder={folder}
          selected={folder.id === selected}
          onSelect={onSelect}
        />
      ))}
    </nav>
  )
}

export type FolderId = 'inbox' | 'sent' | 'drafts'

export type Folder = {
  id: FolderId
  label: string
  unread: number
}

export const FOLDERS: Folder[] = [
  { id: 'inbox', label: 'Inbox', unread: 3 },
  { id: 'sent', label: 'Sent', unread: 0 },
  { id: 'drafts', label: 'Drafts', unread: 1 },
]

export function folderLabel(id: FolderId): string {
  const found = FOLDERS.find((folder) => folder.id === id)
  if (!found) {
    throw new Error(`Unknown folder: ${id}`)
  }
  return found.label
}

